func (t RunEvent) Discriminator() (string, error) {
	var discriminator struct {
		Discriminator string `json:"type"`
	}
	err := json.Unmarshal(t.union, &discriminator)
	return discriminator.Discriminator, err
}

func (t RunEvent) ValueByDiscriminator() (interface{}, error) {
	discriminator, err := t.Discriminator()
	if err != nil {
		return nil, err
	}
	switch discriminator {
	case "compaction_changed":
		return t.AsCompactionChangedEvent()
	case "compaction_finished":
		return t.AsCompactionFinishedEvent()
	case "compaction_started":
		return t.AsCompactionStartedEvent()
	case "conversation_deleted":
		return t.AsConversationDeletedEvent()
	case "generation_started":
		return t.AsGenerationStartedEvent()
	case "message_appended":
		return t.AsMessageAppendedEvent()
	case "part_delta":
		return t.AsPartDeltaEvent()
	case "part_ended":
		return t.AsPartEndedEvent()
	case "part_started":
		return t.AsPartStartedEvent()
	case "retry_scheduled":
		return t.AsRetryScheduledEvent()
	case "run_finished":
		return t.AsRunFinishedEvent()
	case "run_started":
		return t.AsRunStartedEvent()
	case "subagents_changed":
		return t.AsSubagentsChangedEvent()
	case "title_changed":
		return t.AsTitleChangedEvent()
	case "tool_finished":
		return t.AsToolFinishedEvent()
	case "tool_started":
		return t.AsToolStartedEvent()
	case "transcript_changed":
		return t.AsTranscriptChangedEvent()
	default:
		return nil, errors.New("unknown discriminator value: " + discriminator)
	}
}

func (t RunEvent) MarshalJSON() ([]byte, error) {
	b, err := t.union.MarshalJSON()
	return b, err
}

func (t *RunEvent) UnmarshalJSON(b []byte) error {
	err := t.union.UnmarshalJSON(b)
	return err
}

